p=root/'localization/en.json';catalog=json.loads(p.read_text(encoding='utf-8-sig'))
for filename in ['CharacterItems.cs','AncientItems.cs']:
    for line in (root/'src/SpireStrategist.Core'/filename).read_text(encoding='utf-8').splitlines():
        case=re.match(r'\s*"([A-Za-z_]+)"=>',line)
        if case and case[1] in notes:
            literals=re.findall(r'"([^"\n]*)"',line)
            assert re.search('[\u4e00-\u9fff]',literals[-1]),line
            catalog[literals[-1]]=notes[case[1]]
